<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import * as api from '../../api/training'
import type { ComputeRun, SampleRow } from '../../api/training'
import ExperimentChart from '../experiments/ExperimentChart.vue'
const props = defineProps<{ run: ComputeRun }>()
const kind = ref('pairs'), page = ref(1), total = ref(0), rows = ref<SampleRow[]>([]), error = ref(''), loading = ref(false)
const names: Record<string, string> = { controlled_paraphrase: '事实保持改写', rule_supported_negative: '内容差异负例', LENGTH_RATIO: '长度变化过大', NUMBER_SET_CHANGED: '数字发生变化', REQUIRED_ENTITY_CHANGED: '名称发生变化', INSUFFICIENT_REWORDING: '改写幅度不足', NON_ARTICLE_OUTPUT: '包含非正文内容', TOKEN_BUDGET: '生成长度超限', CROSS_PARTITION_REWRITE: '跨分区改写重复', CROSS_PARTITION_SENTENCE: '跨分区文本重复', LABEL_CONFLICT: '标签冲突', SHORT_SEGMENT: '段落过短', REPEATED_SEGMENT_IN_ARTICLE: '稿内段落重复', CROSS_PARTITION_SEGMENT: '跨分区原文重复', DUPLICATE_PAIR: '重复句对', NO_SUPPORTED_NEGATIVE: '未找到有依据负例' }
let ticket = 0
async function load() { const token = ++ticket; loading.value = true; error.value = ''; try { const result = await api.samples(props.run.runId, kind.value, page.value); if (token === ticket) { rows.value = result.items; total.value = result.total } } catch (value) { if (token === ticket) error.value = value instanceof Error ? value.message : '读取样本失败' } finally { if (token === ticket) loading.value = false } }
const sources = computed(() => Object.entries(props.run.result?.labelOrigins ?? {}))
const skipped = computed(() => Object.entries(props.run.result?.skipped ?? {}).filter(([, count]) => count))
const bars = (values: Array<[string, number]>) => ({ tooltip: { trigger: 'axis', borderRadius: 0 }, grid: { left: 150, right: 30, top: 25, bottom: 35 }, xAxis: { type: 'value' }, yAxis: { type: 'category', data: values.map(([name]) => names[name] ?? name) }, series: [{ type: 'bar', data: values.map(([, n]) => n) }] })
onMounted(load); watch(() => props.run.runId, () => { page.value = 1; void load() })
</script>
<template><section class="work-panel"><div class="work-heading"><h2>训练样本结果</h2><div><a :href="api.artifact(run.runId, 'pairs.jsonl')">下载句对</a> · <a :href="api.artifact(run.runId, 'quarantine.jsonl')">下载隔离记录</a></div></div><div class="work-stats"><div><span>处理原稿</span><strong>{{ run.result?.selectedOriginals?.toLocaleString() }}</strong></div><div><span>可用句对</span><strong>{{ run.result?.outputRows?.toLocaleString() }}</strong></div><div><span>隔离记录</span><strong>{{ run.result?.quarantineRows?.toLocaleString() }}</strong></div></div><div class="experiment-grid"><ExperimentChart v-if="sources.length" title="样本标签来源" :option="bars(sources) as any" /><ExperimentChart v-if="skipped.length" title="跳过与待补充原因" :option="bars(skipped) as any" /></div><div class="work-search"><el-radio-group v-model="kind" @change="page = 1; load()"><el-radio-button value="pairs">可用样本</el-radio-button><el-radio-button value="quarantine">隔离记录</el-radio-button></el-radio-group><span v-if="error" role="alert" class="work-error">{{ error }}</span></div><el-table v-loading="loading" :data="rows"><el-table-column type="expand"><template #default="{row}"><div class="sample-detail"><h3>原文</h3><p>{{ row.sentence1 || row.source }}</p><h3>改写 / 对照内容</h3><p>{{ row.sentence2 || row.rewritten }}</p><p v-if="row.sourceOffsets">原文范围：{{ row.sourceOffsets.start }}—{{ row.sourceOffsets.end }}</p><p v-if="row.differenceBasis">负例依据：来源与事件不同，明确过程事实有差异，未发现长段原文复制。</p></div></template></el-table-column><el-table-column label="原文" min-width="180" show-overflow-tooltip><template #default="{row}">{{ row.sentence1 || row.source }}</template></el-table-column><el-table-column label="改写 / 对照" min-width="180" show-overflow-tooltip><template #default="{row}">{{ row.sentence2 || row.rewritten }}</template></el-table-column><el-table-column label="标签 / 原因" min-width="150"><template #default="{row}">{{ row.label !== undefined ? `${row.label === 1 ? '复用' : '非复用'} · ${names[row.label_origin] || row.label_origin}` : row.reasons?.map((reason: string) => names[reason] || reason).join('、') }}</template></el-table-column></el-table><el-pagination layout="prev, pager, next" v-model:current-page="page" :total="total" :page-size="10" @current-change="load" /></section></template>
<style scoped>.sample-detail{padding:10px 20px;white-space:pre-wrap;font-size:13px;line-height:1.8}.sample-detail h3{font-size:14px}.sample-detail p{overflow-wrap:anywhere}</style>
